/* Finance Tracker service worker (generated by scripts/build-sw.mjs — do not edit public/sw.js).
 *
 * Caches ONLY the static app shell (HTML of the static /app pages, JS/CSS, fonts, icons).
 * Financial data is never cached here: it lives encrypted in IndexedDB. /api, /admin and
 * /setup always go to the network.
 */
const VERSION = "__VERSION__";
const CACHE = `ft-shell-${VERSION}`;
const PAGES = __PAGES__;
const ASSETS = __ASSETS__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Add individually so one failing asset doesn't abort the whole install.
      await Promise.all(
        [...PAGES, ...ASSETS].map((url) =>
          fetch(url, { credentials: "same-origin", cache: "reload" })
            .then((res) => (res.ok ? cache.put(url, res) : undefined))
            .catch(() => undefined),
        ),
      );
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith("ft-shell-") && key !== CACHE) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

const NETWORK_ONLY = [/^\/api\//, /^\/admin(\/|$)/, /^\/setup(\/|$)/, /^\/sw\.js$/];

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (NETWORK_ONLY.some((re) => re.test(url.pathname))) return;

  // Next.js client navigations fetch RSC payloads. Offline, fail fast so Next falls back to a
  // full page load, which is then served from the cached HTML below.
  if (req.headers.get("RSC") === "1" || url.searchParams.has("_rsc")) {
    event.respondWith(fetch(req).catch(() => Response.error()));
    return;
  }

  // Immutable build assets: cache first.
  if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/")) {
    event.respondWith(
      caches.open(CACHE).then(async (cache) => {
        const hit = await cache.match(req);
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      }),
    );
    return;
  }

  // Page navigations: the app shell for this version, from cache (query string ignored, e.g.
  // /app/accounts/view?id=…). Falls back to the network for pages not in the shell.
  if (req.mode === "navigate") {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE);
        const path = url.pathname.replace(/\/$/, "") || "/";
        const shell = PAGES.includes(path) ? await cache.match(path) : undefined;
        if (shell) return shell;
        try {
          return await fetch(req);
        } catch {
          return (await cache.match("/app")) || Response.error();
        }
      })(),
    );
  }
});

// ---------------------------------------------------------------- notifications
// Web Push reminders (opt-in). The payload is end-to-end encrypted to this device.
self.addEventListener("push", (event) => {
  let data = { title: "Finance Tracker", body: "You have reminders.", url: "/app", tag: "ft" };
  try {
    data = { ...data, ...(event.data ? event.data.json() : {}) };
  } catch {
    /* keep defaults */
  }
  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      tag: data.tag,
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      data: { url: data.url },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || "/app";
  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const c of all) {
        if (new URL(c.url).origin === self.location.origin) {
          await c.focus();
          if ("navigate" in c) await c.navigate(url);
          return;
        }
      }
      await self.clients.openWindow(url);
    })(),
  );
});
